cases = []
def add(tool, ti, agent="claude", cwd=G, expect="deny ask"):
    cases.append({"id": "s%02d" % (len(cases) + 1), "agent": agent, "tool": tool, "ti": ti, "cwd": cwd, "expect": expect})
def sh(cmd, tool="Bash", **k):
    add(tool, {"command": cmd}, **k)
def cx(cmd, tool="Bash", **k):
    add(tool, {"command": cmd}, agent="codex", **k)
def patch(body, **k):
    add("apply_patch", {"command": "*** Begin Patch\n" + body + "\n*** End Patch"}, agent="codex", **k)
def mcp(tool, ti, agent="claude", **k):
    add(tool, ti, agent=agent, **k)

